def skill():
    X = [1, 2, 3, 6]
    den = num = 0
    for v in X:
        divs = [d for d in X if v % d == 0]
        cnt = 0
        for f2 in divs:
            for f3 in divs:
                cnt += sum(1 for f1 in divs if f2 % f1 == 0 and f3 % f1 == 0)
        den += cnt
        if v == 6:
            num += cnt
    r = Fraction(num, den)
    return r.numerator + r.denominator

def standard():
    from itertools import product
    X = [1, 2, 3, 6]
    tot = fav = 0
    for f in product(X, repeat=4):
        m = dict(zip(X, f))
        if all(m[b] % m[a] == 0 for a in X for b in X if b % a == 0):
            tot += 1
            fav += m[6] == 6
    r = Fraction(fav, tot)
    return r.numerator + r.denominator

def unique():
    return [standard()]
